     3	public class ErroNegocio extends RuntimeException {
     4	
     5	    private final String codigo;
     6	    private final int status;
     7	
     8	    public ErroNegocio(String codigo, int status) {
     9	        super(codigo);
    10	        this.codigo = codigo;
    11	        this.status = status;
    12	    }
    13	
    14	    public static ErroNegocio invalido(String codigo) {
    15	        return new ErroNegocio(codigo, 422);
    16	    }
    17	
    18	    public static ErroNegocio conflito(String codigo) {
    19	        return new ErroNegocio(codigo, 409);
    20	    }
    21	
    22	    public static ErroNegocio naoEncontrado(String codigo) {
    23	        return new ErroNegocio(codigo, 404);
    24	    }
    25	
    26	    public String codigo() {
    27	        return codigo;
    28	    }
    29	
    30	    public int status() {
    31	        return status;
    32	    }
    33	}
