    72	package com.loja.dominio;
    73	
    74	import java.time.Clock;
    75	import java.time.Duration;
    76	import java.time.Instant;
    77	import java.time.temporal.ChronoUnit;
    78	import java.util.List;
    79	import java.util.UUID;
    80	
    81	import org.springframework.stereotype.Service;
    82	
    83	@Service
    84	public class PedidoService {
    85	
    86	    private static final Duration PRAZO_PAGAMENTO = Duration.ofHours(48);
    87	
    88	    private final Armazem armazem;
    89	    private final CalculadoraResumo calculadora;
    90	    private final List<CanalNotificacao> canais;
    91	    private final List<EfeitoPagamento> efeitos;
    92	    private final Clock relogio;
    93	
    94	    public PedidoService(Armazem armazem, CalculadoraResumo calculadora, List<CanalNotificacao> canais,
    95	                         List<EfeitoPagamento> efeitos, Clock relogio) {
    96	        this.armazem = armazem;
    97	        this.calculadora = calculadora;
    98	        this.canais = canais;
    99	        this.efeitos = efeitos;
   100	        this.relogio = relogio;
   101	    }
   102	
   103	    public Resumo resumir(DadosCompra dados) {
   104	        return calculadora.calcular(dados).resumo();
   105	    }
   106	
   107	    public Pedido registrar(DadosCompra dados) {
   108	        CalculadoraResumo.Calculo calculo = calculadora.calcular(dados);
   109	        return armazem.escrever((estado, mudancas) -> {
   110	            String cpf = dados.cliente().cpf();
   111	            if (!estado.clientes.containsKey(cpf)) {
   112	                Cliente cliente = new Cliente(cpf, dados.cliente().email(), Dinheiro.ZERO);
   113	                estado.clientes.put(cpf, cliente);
   114	                mudancas.clientes.add(cliente);
   115	            }
   116	            Pedido pedido = new Pedido(UUID.randomUUID().toString(), cpf, SituacaoPedido.AGUARDANDO_PAGAMENTO,
   117	                    Instant.now(relogio).truncatedTo(ChronoUnit.SECONDS), calculo.resumo(), calculo.itens(),
   118	                    null, null);
   119	            estado.adicionarPedido(pedido);
   120	            mudancas.pedidos.add(pedido);
   121	            return pedido.copia();
   122	        });
   123	    }
   124	
   125	    public Pedido consultar(String id) {
   126	        return armazem.ler(estado -> buscar(estado, id).copia());
   127	    }
   128	
   129	    public Pedido pagar(String id, String idTransacao, String pagoEmTexto) {
   130	        return armazem.escrever((estado, mudancas) -> {
   131	            Pedido pedido = buscar(estado, id);
   132	            if (idTransacao != null && idTransacao.equals(pedido.idTransacao())
   133	                    && pedido.situacao() != SituacaoPedido.AGUARDANDO_PAGAMENTO) {
   134	                return pedido.copia();
   135	            }
   136	            if (!pedido.situacao().permite(SituacaoPedido.PAGO)) {
   137	                throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
   138	            }
   139	            if (idTransacao == null || idTransacao.isBlank()) {
   140	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   141	            }
   142	            Instant momento = momento(pagoEmTexto);
   143	            if (Duration.between(pedido.criadoEm(), momento).compareTo(PRAZO_PAGAMENTO) > 0) {
   144	                cancelarInterno(estado, mudancas, pedido);
   145	                throw ErroNegocio.conflito("PEDIDO_EXPIRADO");
   146	            }
   147	            for (Item item : pedido.itens()) {
   148	                if (estado.produtos.get(item.sku()).estoque() < item.quantidade()) {
   149	                    cancelarInterno(estado, mudancas, pedido);
   150	                    throw ErroNegocio.conflito("ESTOQUE_INSUFICIENTE");
   151	                }
   152	            }
   153	            for (Item item : pedido.itens()) {
   154	                Produto produto = estado.produtos.get(item.sku());
   155	                produto.baixar(item.quantidade());
   156	                mudancas.produtos.add(produto);
   157	            }
   158	            pedido.registrarPagamento(idTransacao);
   159	            mudancas.pedidos.add(pedido);
   160	            efeitos.forEach(e -> e.aplicar(estado, mudancas, pedido));
   161	            avisar(estado, mudancas, pedido, TipoAviso.PAGAMENTO_APROVADO);
   162	            return pedido.copia();
   163	        });
   164	    }
   165	
   166	    public Pedido enviar(String id, String codigoRastreio) {
   167	        return armazem.escrever((estado, mudancas) -> {
   168	            Pedido pedido = buscar(estado, id);
   169	            if (!pedido.situacao().permite(SituacaoPedido.ENVIADO)) {
   170	                throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
   171	            }
   172	            if (codigoRastreio == null || codigoRastreio.isBlank()) {
   173	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   174	            }
   175	            pedido.registrarEnvio(codigoRastreio);
   176	            mudancas.pedidos.add(pedido);
   177	            avisar(estado, mudancas, pedido, TipoAviso.PEDIDO_ENVIADO);
   178	            return pedido.copia();
   179	        });
   180	    }
   181	
   182	    public Pedido entregar(String id) {
   183	        return armazem.escrever((estado, mudancas) -> {
   184	            Pedido pedido = buscar(estado, id);
   185	            pedido.mudarPara(SituacaoPedido.ENTREGUE);
   186	            mudancas.pedidos.add(pedido);
   187	            return pedido.copia();
   188	        });
   189	    }
   190	
   191	    public Pedido cancelar(String id) {
   192	        return armazem.escrever((estado, mudancas) -> {
   193	            Pedido pedido = buscar(estado, id);
   194	            if (!pedido.situacao().permite(SituacaoPedido.CANCELADO)) {
